// Combine CPSC and FDA recalls into one format and skip anything already processed.
const cfg = $('Set Configuration Parameters').first().json;
const names = (v) => (Array.isArray(v) ? v.map((x) => (typeof x === 'string' ? x : (x && x.Name) || '')).filter(Boolean) : (typeof v === 'string' && v ? [v] : []));
const ymd = (s) => (s && /^\d{8}$/.test(s) ? `${s.slice(0, 4)}-${s.slice(4, 6)}-${s.slice(6, 8)}` : String(s || '').slice(0, 10));
const upcsIn = (s) => (String(s || '').match(/\b\d[\d -]{9,16}\d\b/g) || []).map((x) => x.replace(/\D/g, '')).filter((d) => d.length >= 11 && d.length <= 14);

const seen = new Set($('Read Recall Log from Sheets').all().map((i) => String((i.json && i.json['Recall ID']) || '')).filter(Boolean));
const recalls = [];

// CPSC (consumer products): the API returns one item per recall
if ($('Fetch CPSC Recall Data').isExecuted) {
  for (const { json: r } of $('Fetch CPSC Recall Data').all()) {
    if (!r || !r.RecallID) continue;
    const products = (r.Products || []).map((p) => [p.Name, p.Model ? `model ${p.Model}` : '', p.Type].filter(Boolean).join(', '));
    recalls.push({
      id: `CPSC-${r.RecallNumber || r.RecallID}`,
      source: 'CPSC',
      category: 'Consumer product',
      date: String(r.RecallDate || '').slice(0, 10),
      title: r.Title || '',
      products,
      description: String(r.Description || '').slice(0, 1500),
      firms: [...names(r.Manufacturers), ...names(r.Importers), ...names(r.Distributors)],
      soldAt: names(r.Retailers),
      hazard: names(r.Hazards).join('; '),
      remedy: names(r.Remedies).join('; ') || names(r.RemedyOptions).join('; '),
      upcs: (r.ProductUPCs || []).map((u) => String((u && u.UPC) || u).replace(/\D/g, '')).filter(Boolean),
      url: r.URL || 'https://www.cpsc.gov/Recalls',
    });
  }
}

// FDA enforcement reports (food, drugs, devices): one item with a results array per endpoint
const fda = [
  ['Fetch FDA Food Recalls', 'Food'],
  ['Fetch FDA Drug Recalls', 'Drug'],
  ['Fetch FDA Device Recalls', 'Medical device'],
];
for (const [node, category] of fda) {
  if (!$(node).isExecuted) continue;
  for (const { json } of $(node).all()) {
    for (const r of (json && json.results) || []) {
      const text = `${r.product_description || ''} ${r.code_info || ''}`;
      recalls.push({
        id: `FDA-${r.recall_number}`,
        source: 'FDA',
        category,
        date: ymd(r.report_date),
        title: `${r.recalling_firm}: ${String(r.product_description || '').slice(0, 120)}`,
        products: [String(r.product_description || '').slice(0, 600)],
        description: `${r.classification || ''} recall, ${r.status || ''}. Distribution: ${r.distribution_pattern || 'n/a'}. Codes: ${String(r.code_info || '').slice(0, 400)}`,
        firms: [r.recalling_firm].filter(Boolean),
        soldAt: [],
        hazard: r.reason_for_recall || '',
        remedy: `${r.classification || ''} recall (${r.voluntary_mandated || 'n/a'})`,
        upcs: upcsIn(text),
        url: 'https://www.accessdata.fda.gov/scripts/ires/index.cfm',
      });
    }
  }
}

// Drop duplicates inside this run and anything logged on previous runs
const unique = new Map();
for (const r of recalls) if (r.id && !seen.has(r.id) && !unique.has(r.id)) unique.set(r.id, r);
return [...unique.values()].map((r) => ({ json: r }));

// Cheap first pass: score every store product against each recall so only plausible pairs reach the AI.
const cfg = $('Set Configuration Parameters').first().json;
const STOP = new Set(('the and for with from due risk recall recalls recalled hazard hazards product products sold units unit model models '
  + 'inc llc ltd corp company co usa brand new pack set size color black white blue red green pink small medium large '
  + 'per item items oz lb lbs pound pounds count ct each includes include including only also may can will this that into').split(' '));
const words = (s) => String(s || '').toLowerCase().replace(/<[^>]+>/g, ' ').match(/[a-z0-9]+/g) || [];
const toks = (s) => [...new Set(words(s).filter((w) => w.length >= 3 && !STOP.has(w) && !/^\d+$/.test(w)))];
const upcKey = (s) => { const d = String(s || '').replace(/\D/g, '').replace(/^0+/, ''); return d.length >= 8 ? d : ''; };
const minScore = Number(cfg.minCandidateScore) || 40;
const maxCand = Number(cfg.maxCandidatesPerRecall) || 5;

const products = $('Retrieve Shopify Products').all().map((i) => i.json).filter((p) => p && p.id).map((p) => ({
  id: String(p.id),
  title: p.title || '',
  vendor: p.vendor || '',
  type: p.product_type || '',
  status: p.status || '',
  tags: Array.isArray(p.tags) ? p.tags.join(', ') : (p.tags || ''),
  skus: (p.variants || []).map((v) => v.sku).filter(Boolean),
  barcodes: (p.variants || []).map((v) => upcKey(v.barcode)).filter(Boolean),
  _title: toks(`${p.title} ${p.product_type || ''}`),
  _vendor: words(p.vendor).join(' '),
}));

return $input.all().map(({ json: r }) => {
  const text = [r.title, (r.products || []).join(' '), r.description, (r.firms || []).join(' ')].join(' ');
  const rTokens = new Set(toks(text));
  const rWords = ` ${words(text).join(' ')} `;
  const rUpcs = new Set((r.upcs || []).map(upcKey).filter(Boolean));

  const candidates = products.map((p) => {
    let score = 0;
    const why = [];
    if (p.barcodes.some((b) => rUpcs.has(b))) { score = 100; why.push('Barcode matches a recalled UPC'); }
    if (p._vendor.length >= 3 && rWords.includes(` ${p._vendor} `)) { score += 45; why.push(`Brand "${p.vendor}" is named in the recall`); }
    const hits = p._title.filter((t) => rTokens.has(t));
    if (hits.length >= 2 || (hits.length === 1 && p._title.length === 1)) {
      score += Math.round((hits.length / p._title.length) * 55);
      why.push(`Shared words: ${hits.join(', ')}`);
    }
    return { ...p, score: Math.min(score, 100), why };
  })
    .filter((p) => p.score >= minScore)
    .sort((a, b) => b.score - a.score)
    .slice(0, maxCand)
    .map(({ _title, _vendor, ...rest }) => rest);

  return { json: { recall: r, candidates, candidateCount: candidates.length, catalogSize: products.length } };
});

