// Keep only the products the AI confirmed as affected, one item per product.
const cfg = $('Set Configuration Parameters').first().json;
const source = $('Filter Candidate Products').all();
const minConf = Number(cfg.minConfidence) || 70;
const draftConf = Number(cfg.autoDraftConfidence) || 90;
const out = [];

$input.all().forEach((item, i) => {
  const ai = item.json.output || item.json;
  const d = (source[i] && source[i].json) || {};
  const r = d.recall || {};
  for (const m of ai.matches || []) {
    const conf = Number(m.confidence) || 0;
    if (!m.affected || conf < minConf) continue;
    const p = (d.candidates || []).find((c) => String(c.id) === String(m.product_id));
    if (!p) continue; // never act on a product the AI was not shown
    const willDraft = cfg.autoDraftProducts === true && conf >= draftConf && String(p.status).toLowerCase() === 'active';
    out.push({
      json: {
        recallId: r.id,
        source: r.source,
        category: r.category,
        recallDate: r.date,
        recallTitle: r.title,
        hazard: r.hazard,
        remedy: r.remedy,
        firms: (r.firms || []).join(', '),
        recallUrl: r.url,
        productId: p.id,
        productTitle: p.title,
        vendor: p.vendor,
        skus: p.skus.join(', '),
        productStatus: p.status,
        productUrl: `https://admin.shopify.com/store/${cfg.shopifyStoreHandle}/products/${p.id}`,
        confidence: conf,
        reason: m.reason || '',
        lotCheckNeeded: m.lot_check_needed === true,
        recallSummary: ai.recall_summary || '',
        recommendedAction: ai.recommended_action || '',
        willDraft,
        action: willDraft ? 'Listing set to draft automatically' : 'Review needed',
      },
    });
  }
});
return out;

