// One short Slack summary of the run.
const cfg = $('Set Configuration Parameters').first().json;
if (cfg.notifyDailySummary !== true) return [];
const all = $input.all().map((i) => i.json);
const count = (pred) => all.filter(pred).length;
const bySrc = [
  ['CPSC', (x) => x.recall.source === 'CPSC'],
  ['FDA food', (x) => x.recall.category === 'Food'],
  ['FDA drugs', (x) => x.recall.category === 'Drug'],
  ['FDA devices', (x) => x.recall.category === 'Medical device'],
].map(([label, f]) => `${label} ${count(f)}`).join(' | ');
const review = all.filter((x) => x.candidateCount > 0);
const catalog = all.length ? all[0].catalogSize : 0;

const text = [
  `:shield: *Recall check: ${$now.toFormat('yyyy-MM-dd')}*`,
  `${all.length} new recalls checked against ${catalog} products (${bySrc}).`,
  review.length
    ? `${review.length} recall(s) had possible matches and were sent for AI review. Confirmed matches are posted as separate alerts.`
    : 'No recall resembled anything in your catalog.',
].join('\n');
return [{ json: { text } }];
